    /**
     * @ingroup particle
     * @addtogroup Enum
     * @brief How overlapping particles are sorted before rendering.Defaults to UNSORTED
     * \since API Level 1
     */
    enum class ParticleSortOrder : uint8_t {
        DECREASING_AGE = 0,     ///< Particles emitted earlier are rendered before particles emitted more recently.
        DECREASING_ID = 1,      ///< Particles with higher IDs are rendered first
        INCREASING_AGE = 2,     ///< Particles emitted more recently are rendered before particles emitted earlier.
        INCREASING_ID = 3,      ///< Particles with lower IDs are rendered first.
        UNSORTED = 4,           ///< Particles are not sorted; they may be rendered in any order.
        DECREASING_DISTANCE = 5,///< Render particles in descending order according to their distance from the camera.
        INCREASING_DISTANCE = 6,///< Render particles in order from small to large distance from the camera.
    };

