    /**
     * @ingroup tracking_provider
     * @addtogroup Interface
     * \since API Level 1
     */
    class ControllerTrackingProvider final {
    public:
        ControllerTrackingProvider() = delete;
        ControllerTrackingProvider(const ControllerTrackingProvider&) = delete;
        ControllerTrackingProvider(ControllerTrackingProvider&&) = delete;
        ControllerTrackingProvider& operator=(const ControllerTrackingProvider&) = delete;
        ControllerTrackingProvider& operator=(ControllerTrackingProvider&&) = delete;

    public:
        /**
         * Callback function which will be invoked when has new tracking data.
         * @param sensorData The controller tracking result
         * \since API Level 1
         */
        typedef void (*OnControllerTrackingResultUpdatedCallback)(const spatialpack::ControllerTrackingResult& sensorData);
        /**
         * Callback function which will be invoked when has new action result data.
         * @param sensorData The controller action result
         * \since API Level 1
         */
        typedef void (*OnControllerActionResultUpdatedCallback)(const spatialpack::ControllerActionResult& sensorData);

    public:
        /**
         * create the tracking provider
         * @return The created tracking provider in singleton
         * \since API Level 1
         */
        static spatialpack::ControllerTrackingProvider* create();

        /**
         * start the data receiving
         * @return Get the type of the payload event
         * \since API Level 1
         */
        bool start() const;

        /**
         * stop the data receiving
         * @return Get the raw pointer of event
         * \since API Level 1
         */
        bool stop() const;

        /**
         * set the sensor data callback
         * @param callback The callback to receive sensor data
         * \since API Level 1
         */
        void OnControllerTrackingResultReceived(spatialpack::ControllerTrackingProvider::OnControllerTrackingResultUpdatedCallback callback);

        /**
         * set the action result data callback
         * @param callback The callback to receive action result data
         * \since API Level 1
         */
        void OnControllerActionResultReceived(spatialpack::ControllerTrackingProvider::OnControllerActionResultUpdatedCallback callback);

        /**
         * get the tracking provider state
         * \since API Level 1
         */
        spatialpack::TrackingProviderState getState();

        /**
         * get the support state of tracking provider
         * \since API Level 1
         */
        spatialpack::TrackingProviderSupportState getSupportState();
    };

