    /**
     * @ingroup tracking_provider
     * @addtogroup Interface
     * \since API Level 1
     */
    class MotionTrackingProvider final {
    public:
        MotionTrackingProvider() = delete;
        MotionTrackingProvider(const MotionTrackingProvider&) = delete;
        MotionTrackingProvider(MotionTrackingProvider&&) = delete;
        MotionTrackingProvider& operator=(const MotionTrackingProvider&) = delete;
        MotionTrackingProvider& operator=(MotionTrackingProvider&&) = delete;

    public:
        /**
         * Callback function which will be invoked when has new tracking data.
         * @param sensorData The Motion tracking result
         * \since API Level 1
         */
        typedef void (*OnMotionTrackingResultUpdatedCallback)(const spatialpack::MotionTrackingResult& sensorData);
        /**
         * Callback function which will be invoked when motion tracker connection state has updated.
         * @param state The Motion tracker connection info
         * \since API Level 1
         */
        typedef void (*OnMotionTrackerConnectionStateUpdatedCallback)(const spatialpack::MotionTrackerConnectionInfo& state);
        /**
         * Callback function which will be invoked when motion tracker battery charging state has updated.
         * @param state The Motion tracker battery charging info
         * \since API Level 1
         */
        typedef void (*OnMotionTrackerBatteryInfoUpdatedCallback)(const spatialpack::MotionTrackerBatteryInfo& state);
        /**
         * Callback function which will be invoked when motion tracker receive key event
         * @param state The key event of tracker
         * \since API Level 1
         */
        typedef void (*OnMotionTrackerKeyEventReceivedCallback)(const spatialpack::MotionTrackerKeyEvent& state);
        /**
         * Callback function which will be invoked when motion tracker request completed
         * @param state The collection of current connected tracker
         * \since API Level 1
         */
        typedef void (*OnMotionTrackerRequestCompletedCallback)(const spatialpack::MotionTrackerIdCollection& state);

    public:
        /**
         * create the tracking provider
         * @return The created tracking provider in singleton
         * \since API Level 1
         */
        static spatialpack::MotionTrackingProvider* create();

        /**
         * start the data receiving
         * @return Get the type of the payload event
         * \since API Level 1
         */
        bool start() const;

        /**
         * start the data receiving
         * @param info The start info of the tracking provider
         * @return Get the type of the payload event
         * \since API Level 1
         */
        bool startWithInfo(const spatialpack::MotionTrackingStartInfo& info) const;

        /**
         * stop the data receiving
         * @return Get the raw pointer of event
         * \since API Level 1
         */
        bool stop() const;

        /**
         * set the sensor data callback
         * @param callback The callback to receive sensor data
         * \since API Level 1
         */
        void OnMotionTrackingResultReceived(spatialpack::MotionTrackingProvider::OnMotionTrackingResultUpdatedCallback callback);

        /**
         * set the connection state callback
         * @param callback The callback to receive connection state
         * \since API Level 1
         */
        void OnMotionTrackerConnectionStateUpdated(spatialpack::MotionTrackingProvider::OnMotionTrackerConnectionStateUpdatedCallback callback);

        /**
         * set the battery charging info callback
         * @param callback The callback to receive battery charging info
         * \since API Level 1
         */
        void OnMotionTrackerBatteryInfoUpdated(spatialpack::MotionTrackingProvider::OnMotionTrackerBatteryInfoUpdatedCallback callback);

        /**
         * set the key event callback
         * @param callback The callback to receive key event
         * \since API Level 1
         */
        void OnMotionTrackerKeyEventReceived(spatialpack::MotionTrackingProvider::OnMotionTrackerKeyEventReceivedCallback callback);

        /**
         * set the request completed callback
         * @param callback The callback to receive request completed
         * \since API Level 1
         */
        void OnMotionTrackerRequestCompleted(spatialpack::MotionTrackingProvider::OnMotionTrackerRequestCompletedCallback callback);

        /**
         * get the tracking provider state
         * \since API Level 1
         */
        spatialpack::TrackingProviderState getState();

        /**
         * get the support state of tracking provider
         * \since API Level 1
         */
        spatialpack::TrackingProviderSupportState getSupportState();
    };

