    /**
     * @ingroup session
     * @addtogroup Interface
     * @brief A runtime session represents the spatial runtime's intent to display contents.
     * \since API Level 1
     */
    class Session final {
    public:
        Session() = delete;
        Session(const Session&) = delete;
        Session(Session&&) = delete;
        Session& operator=(const Session&) = delete;
        Session& operator=(Session&&) = delete;

    public:
        /**
         * Callback function which is invoked on session update.
         * @param pSession The updating session.
         * \since API Level 1
         */
        typedef void (*SessionCallback)(spatialpack::Session* pSession);
        /**
         * Callback function which is invoked on session state changed.
         * @param pSession The updating session.
         * @param pState The new state of session.
         * \since API Level 1
         */
        typedef void (*SessionStateChangedCallback)(spatialpack::Session* pSession, spatialpack::SessionState pState);
        /**
         * Callback function which is invoked on session begin.
         * @param pSession The updating session.
         * \since API Level 1
         */
        typedef void (*onSessionBeginCallback)(spatialpack::Session* pSession);
        /**
         * Callback function which is invoked on session end.
         * @param pSession The updating session.
         * \since API Level 1
         */
        typedef void (*onSessionEndCallback)(spatialpack::Session* pSession);
        /**
         * Callback function which is invoked on session update.
         * @param pSession The updating session.
         * \since API Level 1
         */
        typedef void (*onSessionUpdateCallback)(spatialpack::Session* pSession);
        /**
         * Callback function which is invoked on session destroy.
         * @param pSession The updating session.
         * \since API Level 1
         */
        typedef void (*onSessionDestroyCallback)(spatialpack::Session* pSession);

    public:
        /**
         * Get a scene which was created by default.
         * @return The scene pointer for app.
         * \since API Level 1
         */
        spatialpack::AppScene* getAppScene();

        /**
         * Add a session state changed callback for session.
         * @param callback The callback with session.
         * \since API Level 1
         */
        void addStateChangedCallback(spatialpack::Session::SessionStateChangedCallback callback);

        /**
         * Remove a session state changed callback for session.
         * @param callback The callback with session.
         * \since API Level 1
         */
        void removeStateChangedCallback(spatialpack::Session::SessionStateChangedCallback callback);

        /**
         * Get the version of session.
         * @return The version of session.
         * \since API Level 1
         */
        static spatialpack::Version getVersion();

        /**
         * Get the build information of session.
         * @return The version of session.
         * \since API Level 1
         */
        static spatialpack::BuildInfo getBuildInfo();

        /**
         * Get the frame duration from last frame to current frame.
         * @return The frame duration from last frame to current frame.
         * \since API Level 1
         */
        float getFrameDeltaTime() const;

        /**
         * Get the time duration from spatial app starts to current time.
         * @return The duration from spatial app starts to current time.
         * \since API Level 1
         */
        float getTimeSinceStartup() const;

        /**
         * Outer driven interface. Start the session.
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult beginSession();

        /**
         * Outer driven interface. End the session.
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult endSession();

        /**
         * Outer driven interface. Throttle the application frame loop, and will block the current thread until received phase sync event
         * @param skip_phase_sync ignore Phase Sync event
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult waitFrame(bool skip_phase_sync);

        /**
         * Outer driven interface. Called prior to the start of frame
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult beginFrame();

        /**
         * Outer driven interface. Called to the end of frame
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult endFrame();

        /**
         * Add a session begin callback for session.
         * @param callback The callback with session begin.
         * \since API Level 1
         */
        void onSessionBegin(spatialpack::Session::onSessionBeginCallback callback);

        /**
         * Remove a session begin callback for session.
         * @param callback The callback of session begin.
         * \since API Level 1
         */
        void removeSessionBeginCallback(spatialpack::Session::onSessionBeginCallback callback);

        /**
         * Add a session end callback for session.
         * @param callback The callback with session end.
         * \since API Level 1
         */
        void onSessionEnd(spatialpack::Session::onSessionEndCallback callback);

        /**
         * Remove a session end callback for session.
         * @param callback The callback of session end.
         * \since API Level 1
         */
        void removeSessionEndCallback(spatialpack::Session::onSessionEndCallback callback);

        /**
         * Add a session update callback for session.
         * @param callback The callback with session update.
         * \since API Level 1
         */
        void onSessionUpdate(spatialpack::Session::onSessionUpdateCallback callback);

        /**
         * Remove a session update callback for session.
         * @param callback The callback of session update.
         * \since API Level 1
         */
        void removeSessionUpdateCallback(spatialpack::Session::onSessionUpdateCallback callback);

        /**
         * Add a session destroy callback for session.
         * @param callback The callback with session Destroy.
         * \since API Level 1
         */
        void onSessionDestroy(spatialpack::Session::onSessionDestroyCallback callback);

        /**
         * Remove a session destroy callback for session.
         * @param callback The callback of session destroy.
         * \since API Level 1
         */
        void removeSessionDestroyCallback(spatialpack::Session::onSessionDestroyCallback callback);

        /**
         * Pull all events
         * @param type which event type is pulled. The parameter uses bitwise operation to specify multiple event types.
         * @return return the collection that contains all event.
         * \since API Level 1
         */
        spatialpack::SessionPullEventCollection pullAllEvents(spatialpack::SessionPullEventType type = SessionPullEventType::ALL) const;
    };

    /**
     * @ingroup physics
     * @addtogroup ValueRef
     * @brief A custom clock which drives the physics simulation, defaults to the engine clock.
     *
     * \since API Level 1
     */
    class SimulationClock final {
    public:
        /**
         * The struct is valid or not.
         * @return The struct is valid or not.
         * \since API Level 1
         */
        bool isValid() const;

        /**
         * Set the fixed time step.
         * @param value
         * \since API Level 1
         */
        void setFixedTimeStep(float value);

        /**
         * Get the fixed time step. Default value is 0.01111.
         * \since API Level 1
         */
        float getFixedTimeStep() const;

        /**
         * Set the maximum allowed time step.
         * @param value
         * \since API Level 1
         */
        void setMaximumAllowedTimeStep(float value);

        /**
         * Get the maximum allowed time step. Default value is 0.04444.
         * \since API Level 1
         */
        float getMaximumAllowedTimeStep() const;

        /**
         * Set the time speed.
         * @param value
         * \since API Level 1
         */
        void setScale(float value);

        /**
         * Get the time speed. Default value is 1.
         * \since API Level 1
         */
        float getScale() const;

        /**
         * Constructor
         * @param fixedTimeStep A frame-rate-independent interval that dictates when physics calculations
         * @param maximumAllowedTimeStep A frame-rate-independent interval that caps the worst case scenario when frame-rate is low. Physics calculations will not be performed for longer time than specified.
         * @param scale The speed at which time progresses. A value of 1 means real-time. A value of .5 means half speed; a value of 2 is double speed.
         * \since API Level 1
         */
        SimulationClock(float fixedTimeStep = 0.01111f, float maximumAllowedTimeStep = 0.04444f, float scale = 1.0f);

        /**
         * Copy constructor
         * @param other
         * \since API Level 1
         */
        SimulationClock(const spatialpack::SimulationClock& other);

        /**
         * Move constructor
         * @param other
         * \since API Level 1
         */
        SimulationClock(spatialpack::SimulationClock&& other);

        /**
         * Copy assigner
         * @param other
         * \since API Level 1
         */
        spatialpack::SimulationClock& operator=(const spatialpack::SimulationClock& other);

        /**
         * Move assigner
         * @param other
         * \since API Level 1
         */
        spatialpack::SimulationClock& operator=(spatialpack::SimulationClock&& other);

        ~SimulationClock() {
            release();
            handler = {0};
        }

    private:
        /**
         * Release the reference count
         * \since API Level 1
         */
        void release();

    private:
        int64_t handler{0};
        uint8_t __padding[24]{};
    };

