        [[nodiscard]] static spatialpack::MeshResourceAsyncLoadJob* createConeAsync(float height, float radius, void* userData = nullptr, spatialpack::MeshResource::MeshResourceAsyncLoadJobCallback callback = nullptr, const char* name = nullptr);

