    public:
        /**
         * Create spatial instance
         * @return The created spatial instance.
         * \since API Level 1
         */
        static spatialpack::SpatialInstance* createOrGetSpatialInstance();

        /**
         * Create a spatial instance. It is a process-level singleton. If this function is invoked multiple times, the result is the same..
         * @return The created spatial instance.
         * \since API Level 1
         */
        static spatialpack::SpatialInstance* createInstance();

        /**
         * Get spatial instance, If an existing spatial instance is invoked, return the process-level singleton instance; otherwise, return nullptr.
         * @return The created spatial instance or nullptr
         * \since API Level 1
         */
        static spatialpack::SpatialInstance* getInstance();

        /**
         * Init SpatialInstance with SpatialInstanceInitInfo
         * @param initInfo
         * \since API Level 1
         */
        spatialpack::SpatialResult initInstanceWithInfo(const spatialpack::SpatialInstanceInitInfo& initInfo);

        /**
         * Get true if SpatialInstance has been initialized, else false
         * \since API Level 1
         */
        bool isInitialized() const;

        /**
         * Create a Session with SpatialSessionCreateInfo
         * @param createInfo The SpatialSessionCreateInfo
         * @param session The pointer of session*, if create session successfully, the pointer will point to a valid Session
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult createSessionWithInfo(const spatialpack::SpatialSessionCreateInfo& createInfo, spatialpack::Session** session);

        /**
         * Destroy a Session
         * @param session The pointer of the session*, which will be destroyed, release the relative resource and set the session* to nullptr
         * \since API Level 1
         */
        void destroySession(spatialpack::Session** session);

        /**
         * get the session which associated to current thread
         * @param session The pointer of session*
         * @return The result of this invoke
         * \since API Level 1
         */
        spatialpack::SpatialResult getSession(spatialpack::Session** session);

        /**
         * Destroy SpatialInstance
         * @param instance The instance to destroy.
         * \since API Level 1
         */
        static void destroyInstance(spatialpack::SpatialInstance* instance);

